use serde::Deserialize;

/// Generated by the NixOS module (nix/locked/executor.nix). Not editable by the agent.
#[derive(Debug, Clone, Deserialize)]
pub struct Config {
    /// Unix user the agent runs as; the only uid accepted on the action socket.
    pub agent_user: String,
    /// Unix user of the HUD gateway; accepted on the approval socket (with root).
    pub hud_user: String,
    pub exec_socket: String,
    pub approve_socket: String,
    pub audit_path: String,
    /// Root-owned JSON file describing the active engagement. May be absent.
    pub engagement_path: String,
    /// Addresses that are never a valid target, whatever the engagement says.
    #[serde(default)]
    pub permanent_deny: Vec<String>,
    pub systemctl: String,
    pub journalctl: String,
    /// Units the agent may never start, stop or restart (the locked core).
    #[serde(default)]
    pub forbidden_units: Vec<String>,
    /// Path to osqueryi. osquery.query is refused when unset.
    #[serde(default)]
    pub osqueryi: Option<String>,
    /// Path to coreutils `timeout`, used to bound osquery's run time.
    #[serde(default)]
    pub timeout_bin: Option<String>,
    /// The only osquery tables a query may read. Anything else (password
    /// hashes, process environments, the curl table) does not exist for it.
    #[serde(default)]
    pub osquery_tables: Vec<String>,
    #[serde(default = "default_ttl")]
    pub approval_ttl_ms: u64,
    /// Screenshots of the kiosk display. screen.capture is refused when unset.
    #[serde(default)]
    pub screen: Option<Screen>,
    /// Self-modification of the system configuration. The config.* actions
    /// are refused when unset.
    #[serde(default)]
    pub selfmod: Option<SelfMod>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Screen {
    /// The user whose Wayland session shows the HUD.
    pub user: String,
    pub grim: String,
    pub setpriv: String,
    pub timeout: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct SelfMod {
    /// The configuration the running system was built from (a path that
    /// resolves into the Nix store).
    pub source: String,
    /// Root-owned directory for candidates and job status.
    pub state_dir: String,
    pub nix: String,
    pub diff: String,
    pub timeout: String,
    pub systemd_run: String,
    /// The root job script: `check`, and `apply <candidate dir>`.
    pub script: String,
    /// Repository paths that always need human approval. A trailing "/"
    /// means everything below.
    #[serde(default)]
    pub locked_paths: Vec<String>,
}

fn default_ttl() -> u64 {
    10 * 60 * 1000
}

impl Config {
    pub fn load(path: &str) -> Result<Config, String> {
        let text = std::fs::read_to_string(path).map_err(|e| format!("read {path}: {e}"))?;
        serde_json::from_str(&text).map_err(|e| format!("parse {path}: {e}"))
    }
}
